"""Deterministic interpretation notes alongside (not generated by) the local LLM."""


def interpretation_snapshot(record):
    state=record.get('state',{});core=state.get('core',{});work=state.get('workspaces',{})
    image=record.get('image');notes=[];reports={};findings=[]
    if image:
        info=image['info']
        notes.append('Stored channel labels are supplied metadata or owner annotations, not independently verified biological identities. Do not infer marker identity from a filename, dye name or LUT. Corrected identities supersede earlier marker-specific prose; a changed reference channel requires new candidate selection.')
        missing=[a for a,c in info.get('calibration',{}).items() if c.get('value_um') is None or c.get('conflict')]
        if missing:notes.append('Physical sampling is unknown or conflicting for '+', '.join(missing)+'. Do not infer calibrated distances on those axes.')
        if str(info.get('acquisition',{}).get('stored_color_model','')).startswith('RGB'):notes.append('Stored RGB components may be display colours rather than independently acquired molecular channels.')
    else:notes.append('No current image is supplied. General methodological advice is available; there are no current-image findings.')
    analysis=core.get('analysis')
    if isinstance(analysis,dict):
        if analysis.get('request',{}).get('threshold_mode')=='zero':notes.append('ROI Manders uses zero thresholds. Positive background can increase overlap; inspect background and threshold sensitivity before interpretation.')
        for row in analysis.get('results',[])[:10]:
            for pair in row.get('pairs',[])[:6]:
                a,b=pair.get('label_a'),pair.get('label_b')
                if a and b:notes.append(f'Engine-defined marker order: M1 is the fraction of {a} intensity at pixels where {b} exceeds its threshold; M2 is the fraction of {b} intensity where {a} exceeds its threshold. Read the recorded values in that order. These are intensity fractions, not shared volume or binding probabilities.')
            for channel in row.get('channel_summary',[]):
                if channel.get('std')==0:notes.append(str(channel.get('label','A channel'))+(' is all zero in a selected ROI. High-intensity saturation is not an explanation for this recorded zero range.' if channel.get('sum')==0 else ' has constant intensity in a selected ROI.')+' Correlation is undefined; this does not establish biological absence. Changing a threshold cannot restore intensity variation.')
        notes.append('ROI coefficients describe selected image regions; they do not establish binding or independent biological replication.')
    keys={'cuboid':'OrthogonalWorkspace.report','segmentation':'Segmentation.report','spatial':'ValidationPanel.spatial','sensitivity':'ValidationPanel.sensitivity','acquisition':'ChannelPanel.quality'}
    for kind,key in keys.items():
        report=work.get(key)
        if not isinstance(report,dict):continue
        if not image or report.get('source_sha256')!=image.get('sha256') or report.get('image_info')!=image['info']:
            notes.append(kind.capitalize()+' report excluded: source or image settings differ from the current image.');continue
        if kind=='acquisition' and 'z' in core and report.get('z')!=core['z']:
            notes.append('Signal check excluded: it describes a different Z plane. Run a check for the current plane.');continue
        if kind=='segmentation':
            reports[kind]={k:report.get(k) for k in ('request','threshold','foreground_voxels','object_count','units','proximity','scope')}
            objects=report.get('objects',[])
            reports[kind]['objects_touching_cuboid_edge']=sum(o.get('touches_cuboid_edge') is True for o in objects)
            reports[kind]['objects_preview']=objects[:3]
            reports[kind]['objects_omitted']=max(0,len(objects)-3)
            radial=report.get('radial_enrichment')
            if radial:reports[kind]['radial_definition']=radial.get('definition')
            proximity=report.get('proximity') or {}
            if proximity.get('unavailable_reason'):findings.append('Proximity unavailable: '+proximity['unavailable_reason']+' This describes the selected cuboid, not protein absence from the cell; the fraction is undefined rather than zero.')
            if proximity.get('marker_to_reference') and proximity.get('reference_to_marker'):findings.append('Both proximity directions are already calculated. Each fraction uses its own source-foreground voxel count with equal voxel weighting; read the recorded quantities below.')
            if proximity:findings.append('Reference search is limited to the selected cuboid. Voxel-centre geometry is separate from molecular binding and optical resolution.')
            if proximity.get('unavailable_reason'):notes.append('Proximity is unavailable in this cuboid: '+proximity['unavailable_reason']+' An empty cropped mask does not establish absence of the protein from the cell; undefined distance/fraction is not zero probability.')
            if proximity.get('marker_to_reference') and proximity.get('reference_to_marker'):notes.append('Both proximity directions are already recorded. Read the two summaries directly; rerunning is needed only after changing image, mask or measurement settings. Equal fractions are possible in some geometries; reversing direction does not guarantee unequal results.')
            notes.append('Proximity uses separate directed foreground denominators and reference signal inside the selected cuboid only. Outside reference signal is not searched; zero distance means coincident occupied voxel centres, not zero molecular separation. Threshold/ROI choices and anisotropic Z/Y/X spacing affect the result.')
            notes.append('Segmentation identifies threshold-defined foreground in the selected cuboid, not an automatic organelle identity. Edge-touching objects may be truncated; proximity describes occupied voxel centers, not molecular binding distances.')
        else:
            reports[kind]={k:report.get(k) for k in ('request','z','channels','pairs','voxel_count','region_volume_um3','scope','calibration_notes','results','definition') if k in report}
        if kind=='acquisition':notes.append('Signal checks describe only the recorded XY plane. Storage-ceiling pixels do not establish detector saturation; no ceiling pixels does not exclude acquisition clipping below that ceiling.')
    experiment=work.get('ExperimentPanel.report')
    if isinstance(experiment,dict) and experiment.get('request',{}).get('run_id')==work.get('ExperimentPanel.runId'):
        reports['experiment']={k:experiment.get(k) for k in ('algorithm','request','selected_channel_labels','groups','contrasts','aggregation','multiple_comparisons','scope')}
        notes.append('The experiment comparison belongs to its batch, not necessarily the current image. Effects and intervals are conditional on the selected design; pixels, Z planes and multiple ROIs are not independent experiments. Bayesian intervals depend on the supplied prior; a likelihood ratio is not a binding posterior.')
    elif experiment:notes.append('Experiment report excluded: its selected batch does not match.')
    if not reports and not analysis:notes.append('No matching measurement report is supplied. Missing documentation does not prove experiments were not performed.')
    return {'source_id':'interpretation','scope':'Application-generated reading guide from supplied reports; not independent biological validation or an LLM finding.',
            'notes':list(dict.fromkeys(notes)),'reports':reports,'findings':findings,
            'evidence_rules':['Separate measured findings, database associations, general advice and hypothetical knockdown scenarios.',
                              'STRING scores are association evidence, not ROI binding probabilities. KEGG membership/map presence is not measured pathway activation.',
                              'Use citations only for the record they support. Do not infer a protein identity from dye, LUT colour or a filename.']}
